        $storage_percentage = ($current_storage_used / $max_storage_size) * 100;
    }
}



// One short socket.io (Engine.IO v4 polling) session as the live page's
// "Music Controller": REGISTER, send the packets, collect the named replies
// until each has arrived or about four seconds pass, then leave.
function beta_mu_ws(string $key, array $packets, array $want = []): ?array {
    $base = 'https://websocket.botofthespecter.com/socket.io/?EIO=4&transport=polling';
    $req = function (string $url, ?string $body = null, int $to = 6) {
        $ch = curl_init($url);
        curl_setopt_array($ch, [CURLOPT_RETURNTRANSFER => true, CURLOPT_TIMEOUT => $to, CURLOPT_CONNECTTIMEOUT => 3]);
        if ($body !== null) { curl_setopt($ch, CURLOPT_POST, true); curl_setopt($ch, CURLOPT_POSTFIELDS, $body); curl_setopt($ch, CURLOPT_HTTPHEADER, ['Content-Type: text/plain;charset=UTF-8']); }
        $out = curl_exec($ch); $code = (int) curl_getinfo($ch, CURLINFO_HTTP_CODE); curl_close($ch);
        return ($out === false || $code !== 200) ? null : (string) $out;
    };
    $open = $req($base . '&t=' . bin2hex(random_bytes(4)));
    if ($open === null || ($open[0] ?? '') !== '0') return null;
    $sid = (string) (json_decode(substr($open, 1), true)['sid'] ?? '');
    if ($sid === '') return null;
    $u = $base . '&sid=' . rawurlencode($sid);
    $got = [];
    $poll = function (int $to) use ($req, $u, &$got) {
        $r = $req($u . '&t=' . bin2hex(random_bytes(4)), null, $to);
        if ($r === null) return false;
        foreach (explode("\x1e", $r) as $pkt) {
            if ($pkt === '2') { $req($u, '3'); continue; }
            if (strpos($pkt, '40') === 0) { $got['_open'] = true; continue; }
            if (strpos($pkt, '42') === 0) { $ev = json_decode(substr($pkt, 2), true); if (is_array($ev) && isset($ev[0])) $got[(string) $ev[0]] = $ev[1] ?? null; }
        }
        return true;
    };
    $until = function (string $ev, int $tries) use ($poll, &$got) { for ($i = 0; $i < $tries && !array_key_exists($ev, $got); $i++) { if (!$poll(4)) return false; } return array_key_exists($ev, $got); };
    $ok = false;
    if ($req($u, '40') !== null && $until('_open', 3)
        && $req($u, '42' . json_encode(['REGISTER', ['code' => $key, 'channel' => 'Dashboard', 'name' => 'Music Controller']])) !== null && $until('SUCCESS', 4)) {
        $ok = true;
        foreach ($packets as $p) { if ($req($u, '42' . json_encode($p)) === null) { $ok = false; break; } }
        if ($ok) {
            $end = microtime(true) + 4;
            foreach ($want as $ev) { while (!array_key_exists($ev, $got) && microtime(true) < $end) { if (!$poll(max(1, (int) ceil($end - microtime(true))))) break; } }
        }
    }
    $req($u, '41');
    return $ok ? $got : null;
}
